# rerun all kept programs on their kept pairs with lib.py as saved
import glob, importlib.util, traceback
ok=True
for f in sorted(glob.glob('task-*.py')):
    tid=f[:-3]
    try:
        pairs=json.load(open(tid+'.json'))
    except Exception:
        continue
    spec=importlib.util.spec_from_file_location(tid,f)
    m=importlib.util.module_from_spec(spec)
    try:
        spec.loader.exec_module(m)
        res=[m.transform(pr['input'])==pr['output'] for pr in pairs]
        if not all(res): ok=False; print(tid,'FAIL',res)
    except Exception as e:
        ok=False; print(tid,'ERROR',e)
print('all ok' if ok else 'problems above')
